function productCard(n,title,tag,copy,photo,route,delay){return '<article class="product-card" data-reveal data-reveal-delay="'+(delay||0)+'"><div class="product-art '+(photo?'product-art--dark':'')+'">'+(photo?'<img loading="lazy" src="'+asset(photo)+'" alt="'+title+' product visual from the source asset library">':'<div class="product-placeholder"><span class="product-placeholder-ring"></span><span class="product-placeholder-cross"></span><span class="product-placeholder-label">SYSTEM / '+n+'</span></div>')+'</div><div class="product-card-body"><span class="pill">'+tag+'</span><h3>'+title+'</h3><p>'+copy+'</p><a class="text-link" href="'+url(route)+'">Explore system <span>'+arrow()+'</span></a></div></article>';}
function home(){return '<main><section class="hero"><canvas class="hero-canvas" id="radarCanvas" aria-label="Animated radar-style visual showing a rotating scan sweep and tracked aerial objects"></canvas><div class="hero-telemetry"><span><i class="live-dot"></i>TRACKING SIMULATION</span><strong>AIRSPACE / 01</strong><span>SCAN MODE · ACTIVE</span><span>THREAT PICTURE / LIVE</span></div><div class="container"><div class="hero-copy"><p class="eyebrow eyebrow--light">Counter-uncrewed aerial systems</p><h1>Detect. Track.<br><em>Respond.</em></h1><p class="lede">Anmay Defence develops AI-enabled counter-drone systems to help operators understand aerial activity and make faster, clearer decisions around protected airspace.</p><div class="hero-actions"><a class="btn" href="'+url('products')+'">Explore STRIKE systems '+arrow()+'</a><a class="btn btn--white" href="'+url('contact')+'">Request a briefing</a></div><div class="hero-meta"><span><b>01</b> Airspace awareness</span><span><b>02</b> Track continuity</span><span><b>03</b> Decision support</span></div></div></div><div class="hero-bottom"><span><strong>ANMAY DEFENCE</strong> / SYSTEM OVERVIEW</span><span>ILLUSTRATIVE RADAR DISPLAY · NOT OPERATIONAL DATA</span></div></section>'+
'<section class="section"><div class="container">'+sectionHead('The operating environment','A changing threat needs a connected response.','Small unmanned aircraft can create outsized disruption around sensitive facilities, industrial sites and public-facing operations. A clear shared picture helps teams act with greater confidence.')+'<div class="grid-3">'+capability('01','See the activity','Bring aerial observations into an understandable operational picture.',1)+capability('02','Understand the track','Maintain context around movement, position and potential threat relevance.',2)+capability('03','Support the response','Give operators clearer information for a timely, coordinated decision.',3)+'</div></div></section>'+
'<section class="section section--dark"><div class="container">'+sectionHead('The Anmay approach','From detection to decision.','An integrated workflow is designed to reduce fragmented awareness and give operators a consistent view of the situation.')+'<div class="step-list"><article class="step" data-reveal><span class="number">01 / DETECT</span><div><h3>Surface activity in protected airspace</h3><p>Detection options are selected to suit the environment, threat picture and deployment requirement.</p></div><span class="step-mark">↗</span></article><article class="step" data-reveal><span class="number">02 / TRACK</span><div><h3>Build continuity, not isolated alerts</h3><p>Present movement as a track that can be interpreted in an operational context.</p></div><span class="step-mark">↗</span></article><article class="step" data-reveal><span class="number">03 / ASSESS</span><div><h3>Make priorities more legible</h3><p>AI-enabled analysis can assist the operator workflow. Final configuration and functionality must be confirmed for each system.</p></div><span class="step-mark">↗</span></article><article class="step" data-reveal><span class="number">04 / RESPOND</span><div><h3>Connect insight to action</h3><p>Share an actionable view with the responsible team and the configured response layer.</p></div><span class="step-mark">↗</span></article></div><div style="margin-top:30px"><a class="btn btn--white" href="'+url('technology')+'">Explore the technology '+arrow()+'</a></div></div></section>'+
'<section class="section section--fog"><div class="container">'+sectionHead('Product families','Platforms built for different mission contexts.','Explore the product families represented in the current source material. Public specifications and exact configurations are available through an approved briefing.')+'<div class="grid-3">'+productCard('01','STRIKE Gen 1','STRIKE FAMILY','The first-generation STRIKE platform, documented in the available product catalogue and associated footage.','assets/images/strikeGen1/strikeGen1ProductRenderCapture1789709095867.jpg','products',1)+productCard('02','STRIKE Gen 2','NEXT-GENERATION PLATFORM','A newer STRIKE variant with product render and radar-equipped visual material in the asset library.','assets/images/strikeGen2/strikeGen2ProductConceptRender.png','products',2)+productCard('03','STRIKE M','MOUNTED CONFIGURATION','A configurable platform illustrated in source imagery and testing footage. Deployment context and configuration should be reviewed with the team.','assets/images/strikeM/strikeMAutomatedLightMachineGunMountProductPhoto.png','products',3)+'</div><div style="margin-top:28px"><a class="text-link" href="'+url('products')+'">View all product families <span>'+arrow()+'</span></a></div></div></section>'+
'<section class="section"><div class="container feature-split"><div class="feature-copy" data-reveal><p class="kicker">Designed around the operator</p><h2>Clarity at the point of decision.</h2><p class="lede">A counter-drone system is more than a sensor or a device. The operator needs a usable picture, understandable alerts and an agreed response workflow.</p><div class="feature-points"><div class="feature-point"><b>01</b><span>Operational picture built for at-a-glance understanding</span></div><div class="feature-point"><b>02</b><span>Configuration shaped around site, platform and mission context</span></div><div class="feature-point"><b>03</b><span>Technical detail shared through controlled product briefings</span></div></div><div style="margin-top:28px"><a class="text-link" href="'+url('solutions')+'">Explore mission solutions <span>'+arrow()+'</span></a></div></div><div class="feature-media image-frame image-frame--contain" data-reveal data-reveal-delay="2"><img loading="lazy" src="'+asset('assets/images/droneDetection/annotatedRifleMountAssemblyDiagramWithSensorCameraAndGearComponents.jpg')+'" alt="Annotated assembly diagram from the original Anmay Defence asset library, showing a sensor and camera assembly, brackets and mechanical components"></div></div></section>'+
'<section class="section section--fog"><div class="container">'+sectionHead('Mission environments','Protection that can be shaped to the site.','Requirements are different across defence, industrial infrastructure and temporary deployments. The first step is to define the airspace, the operating environment and the response protocol.')+'<div class="grid-2"><article class="panel panel-pad" data-reveal><p class="number">01 / FIXED SITE</p><h3 style="margin-top:38px">Facilities & critical infrastructure</h3><p>Support for airspace awareness around installations, industrial assets, logistics hubs and other sensitive sites.</p><a class="text-link" href="'+url('solutions')+'">Explore fixed-site solutions <span>'+arrow()+'</span></a></article><article class="panel panel-pad" data-reveal data-reveal-delay="1"><p class="number">02 / MOBILE OR TEMPORARY</p><h3 style="margin-top:38px">Field operations & planned events</h3><p>Deployment planning for changing perimeters, temporary protected zones and operational teams that need a shared view.</p><a class="text-link" href="'+url('solutions')+'">Explore deployment models <span>'+arrow()+'</span></a></article></div></div></section>'+
'<section class="section"><div class="container">'+sectionHead('A practical partnership','Built for real operating conditions.','Anmay Defence material includes product concepts, technical imagery and trial footage. Specific deployments and performance details should be presented only when approved for public release.')+'<div class="grid-4"><div class="panel panel-pad" data-reveal><span class="number">A / 01</span><h3 style="margin-top:28px">Applied engineering</h3><p style="font-size:13px">Product design and integration work grounded in the hardware shown in the source library.</p></div><div class="panel panel-pad" data-reveal data-reveal-delay="1"><span class="number">A / 02</span><h3 style="margin-top:28px">System thinking</h3><p style="font-size:13px">Sensor, operator-interface and response concepts considered as one workflow.</p></div><div class="panel panel-pad" data-reveal data-reveal-delay="2"><span class="number">A / 03</span><h3 style="margin-top:28px">Mission fit</h3><p style="font-size:13px">Configuration discussions start from the protected location, environment and operating need.</p></div><div class="panel panel-pad" data-reveal data-reveal-delay="3"><span class="number">A / 04</span><h3 style="margin-top:28px">Controlled detail</h3><p style="font-size:13px">Performance and customer information belongs in approved, purpose-specific briefings.</p></div></div></div></section>'+
footerCta('Let’s define the airspace you need to protect.','Share the environment, the mission and the questions that matter. The briefing request tool prepares a message locally for you to send through an approved contact channel.')+'</main>';}
