window.addEventListener('scroll',updateProgress,{passive:true});updateProgress();
if('IntersectionObserver' in window&&!reduceMotion){var revealObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target);}});},{threshold:.12,rootMargin:'0px 0px -30px 0px'});document.querySelectorAll('[data-reveal]').forEach(function(el){revealObserver.observe(el);});}else{document.querySelectorAll('[data-reveal]').forEach(function(el){el.classList.add('is-visible');});}
var compare=document.getElementById('productCompare');
if(compare){var tabs=[].slice.call(compare.querySelectorAll('[data-product]'));function selectProduct(key){var p=productData[key]||productData.gen1;tabs.forEach(function(t){t.setAttribute('aria-selected',String(t.dataset.product===key));});document.getElementById('compareName').textContent=p.name;document.getElementById('compareDescription').textContent=p.description;document.getElementById('compareStatus').textContent=p.status;document.getElementById('compareRows').innerHTML=comparisonRows(key);}tabs.forEach(function(t){t.addEventListener('click',function(){selectProduct(t.dataset.product);});});}
var briefing=document.getElementById('briefingForm');
if(briefing){briefing.addEventListener('submit',function(e){e.preventDefault();var get=function(id){var el=document.getElementById(id);return el?el.value.trim():'';};var interest=get('interest');if(!interest){document.getElementById('formStatus').textContent='Please select an area of interest to prepare the draft.';return;}var lines=['ANMAY DEFENCE — PRODUCT BRIEFING REQUEST','', 'Organisation: '+(get('org')||'Not specified'),'Role: '+(get('role')||'Not specified'),'Area of interest: '+interest,'Planning horizon: '+(get('timeline')||'Not specified'),'Operating environment: '+(get('environment')||'Not specified'),'Reply contact: '+(get('replyTo')||'Not specified'),'','Context and questions:',get('context')||'Not specified','','Please share the current approved product information and any applicable configuration or integration constraints.'];var draft=lines.join('\n');document.getElementById('draftText').value=draft;document.getElementById('draftWrap').classList.add('is-visible');document.getElementById('formStatus').textContent='Draft prepared locally. Nothing has been sent or saved by this website.';});var reset=briefing.querySelector('button[type=reset]');if(reset){reset.addEventListener('click',function(){document.getElementById('draftWrap').classList.remove('is-visible');document.getElementById('formStatus').textContent='This tool keeps the information in your browser. Submitting does not send a message.';});}var copy=document.getElementById('copyDraft');if(copy){copy.addEventListener('click',function(){var ta=document.getElementById('draftText');ta.focus();ta.select();var status=document.getElementById('formStatus');if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(ta.value).then(function(){status.textContent='Draft copied. Paste it into your approved contact channel.';}).catch(function(){document.execCommand('copy');status.textContent='Draft selected for copying. Paste it into your approved contact channel.';});}else{document.execCommand('copy');status.textContent='Draft selected for copying. Paste it into your approved contact channel.';}});}var download=document.getElementById('downloadDraft');if(download){download.addEventListener('click',function(){var blob=new Blob([document.getElementById('draftText').value],{type:'text/plain;charset=utf-8'});var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='anmay-defence-briefing-request.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href);},1000);});}}
function initRadar(){var canvas=document.getElementById('radarCanvas');if(!canvas||reduceMotion||!canvas.getContext)return;var ctx=canvas.getContext('2d');if(!ctx)return;var w=0,h=0,dpr=1,raf=0,started=performance.now(),last=0;var targets=[{x:.65,y:.3,name:'TRACK 01',amp:.1},{x:.8,y:.57,name:'TRACK 02',amp:1.8},{x:.57,y:.69,name:'TRACK 03',amp:3.2},{x:.88,y:.28,name:'TRACK 04',amp:4.1}];function resize(){var rect=canvas.getBoundingClientRect();w=Math.max(1,rect.width);h=Math.max(1,rect.height);dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}function draw(now){if(document.hidden){raf=requestAnimationFrame(draw);return;}if(now-last<28){raf=requestAnimationFrame(draw);return;}last=now;var time=(now-started)/1000;ctx.clearRect(0,0,w,h);var cx=w*.73,cy=h*.53,R=Math.min(w*.47,h*.59);ctx.save();ctx.strokeStyle='rgba(205,216,243,.12)';ctx.lineWidth=1;for(var gx=0;gx<w;gx+=58){ctx.beginPath();ctx.moveTo(gx,0);ctx.lineTo(gx,h);ctx.stroke();}for(var gy=0;gy<h;gy+=58){ctx.beginPath();ctx.moveTo(0,gy);ctx.lineTo(w,gy);ctx.stroke();}ctx.restore();ctx.save();ctx.translate(cx,cy);ctx.strokeStyle='rgba(183,199,236,.25)';ctx.lineWidth=1;for(var i=1;i<=5;i++){ctx.beginPath();ctx.arc(0,0,R*i/5,0,Math.PI*2);ctx.stroke();}ctx.setLineDash([3,8]);ctx.strokeStyle='rgba(180,195,227,.22)';ctx.beginPath();ctx.moveTo(-R,0);ctx.lineTo(R,0);ctx.moveTo(0,-R);ctx.lineTo(0,R);ctx.stroke();ctx.setLineDash([]);var angle=(time*.42)%(Math.PI*2);var sweep=ctx.createRadialGradient(0,0,0,0,0,R);sweep.addColorStop(0,'rgba(30,90,249,.02)');sweep.addColorStop(.7,'rgba(30,90,249,.05)');sweep.addColorStop(1,'rgba(30,90,249,.3)');ctx.fillStyle=sweep;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,R,angle-.46,angle);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba(93,132,255,.95)';ctx.lineWidth=1.6;ctx.shadowColor='rgba(30,90,249,.9)';ctx.shadowBlur=13;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(angle)*R,Math.sin(angle)*R);ctx.stroke();ctx.shadowBlur=0;ctx.restore();targets.forEach(function(t,idx){var tx=t.x*w+Math.sin(time*.31+t.amp)*9,ty=t.y*h+Math.cos(time*.25+t.amp)*7;var r=7+Math.abs(Math.sin(time*1.8+t.amp))*6;ctx.save();ctx.strokeStyle=idx===1?'rgba(120,159,255,.95)':'rgba(210,222,250,.7)';ctx.fillStyle=idx===1?'#83a1ff':'#e5ebfa';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(tx-12,ty);ctx.lineTo(tx-4,ty);ctx.moveTo(tx+4,ty);ctx.lineTo(tx+12,ty);ctx.moveTo(tx,ty-12);ctx.lineTo(tx,ty-4);ctx.moveTo(tx,ty+4);ctx.lineTo(tx,ty+12);ctx.stroke();ctx.beginPath();ctx.arc(tx,ty,r,0,Math.PI*2);ctx.strokeStyle=idx===1?'rgba(30,90,249,.55)':'rgba(217,226,247,.24)';ctx.stroke();ctx.beginPath();ctx.arc(tx,ty,2,0,Math.PI*2);ctx.fill();if(idx===1){ctx.strokeStyle='rgba(131,161,255,.9)';ctx.strokeRect(tx-21,ty-21,42,42);ctx.fillStyle='#b9c8ff';ctx.font='10px "JetBrains Mono", monospace';ctx.fillText('TRACK 02',tx+27,ty-11);ctx.fillStyle='rgba(174,188,219,.9)';ctx.font='9px "JetBrains Mono", monospace';ctx.fillText('CLASS / REVIEW',tx+27,ty+4);}ctx.restore();});ctx.save();ctx.fillStyle='rgba(165,183,227,.6)';ctx.font='10px "JetBrains Mono", monospace';ctx.fillText('AZ  /  '+String(Math.round(((angle%(Math.PI*2))/(Math.PI*2))*360)).padStart(3,'0')+'°',Math.max(20,cx-R+15),Math.max(20,cy-R+22));ctx.fillText('SWEEP',Math.max(20,cx-R+15),Math.max(35,cy-R+38));ctx.restore();raf=requestAnimationFrame(draw);}resize();window.addEventListener('resize',resize,{passive:true});document.addEventListener('visibilitychange',function(){if(!document.hidden&&!raf)raf=requestAnimationFrame(draw);});raf=requestAnimationFrame(draw);}
